import { Button, Popup, Space } from "react-kui";
export default function App() {
  return (
    <Space wrap>
      {(["click", "hover", "focus", "contextmenu"] as const).map((trigger) => (
        <Popup
          key={trigger}
          trigger={trigger}
          arrow
          openDelay={150}
          closeDelay={300}
          overlay={<span>Opened by {trigger}</span>}
        >
          <Button>{trigger}</Button>
        </Popup>
      ))}
      <Popup disabled overlay="Unavailable">
        <Button disabled>Disabled</Button>
      </Popup>
    </Space>
  );
}

import { useState } from "react";
import { Button, Checkbox, Popup, Space } from "react-kui";
export default function App() {
  const [arrow, setArrow] = useState(true);
  const placements = [
    "top-left",
    "top",
    "top-right",
    "bottom-left",
    "bottom",
    "bottom-right",
    "left-top",
    "left",
    "left-bottom",
    "right-top",
    "right",
    "right-bottom",
  ] as const;
  return (
    <Space vertical>
      <Checkbox checked={arrow} onChange={(event) => setArrow(event.checked)}>
        Show arrow
      </Checkbox>
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(3, minmax(0, 1fr))",
          gap: 8,
          maxWidth: 420,
        }}
      >
        {placements.map((placement) => (
          <Popup
            key={placement}
            placement={placement}
            arrow={arrow}
            offset={10}
            overlay={<span>{placement}</span>}
          >
            <Button>{placement}</Button>
          </Popup>
        ))}
      </div>
    </Space>
  );
}

import { useRef, useState } from "react";
import { Button, Popup, Space, type PopupOpenReason, type PopupRef } from "react-kui";
export default function App() {
  const [open, setOpen] = useState(false);
  const [reason, setReason] = useState<PopupOpenReason>("programmatic");
  const popup = useRef<PopupRef>(null);
  return (
    <Space vertical>
      <Space>
        <Button
          onClick={(event) => {
            // This button is outside the anchor; do not treat this opening click as an outside click.
            event.stopPropagation();
            popup.current?.open();
          }}
        >
          Open via ref
        </Button>
        <Popup
          ref={popup}
          trigger="manual"
          open={open}
          onOpenChange={(next, detail) => {
            setOpen(next);
            setReason(detail.reason);
          }}
          overlay={({ close }) => (
            <Space vertical>
              <span>Click outside or press Escape.</span>
              <Button onClick={close}>Close from inside</Button>
            </Space>
          )}
        >
          <Button onClick={() => setOpen(!open)}>Toggle controlled popup</Button>
        </Popup>
      </Space>
      <span role="status">
        Open: {String(open)} · Reason: {reason}
      </span>
    </Space>
  );
}

import { useRef } from "react";
import { Button, Popup } from "react-kui";
export default function App() {
