import { useRef, useState } from "react";
import {
  Button,
  Input,
  message,
  Modal,
  Space,
  Tag,
  Form,
  FormItem,
  type FormExpose,
  type FormSubmitEvent,
  type FormRule,
} from "react-kui";
const labelCol = { span: 6 },
  wrapperCol = { span: 16 };
export default function App() {
  const ref = useRef<FormExpose>(null);
  const [visible, setVisible] = useState(false),
    [group, setGroup] = useState<{ name: string; list: { username: string; age: string }[] }>({
      name: "",
      list: [],
    }),
    [form, setForm] = useState({ username: "", age: "" });
  const rules = { name: [{ required: true, message: "Please input the organization name" }] };
  const userRules = {
    username: [{ required: true, message: "Please input the organization name" }],
    age: [
      { required: true, message: "Please input the age." },
      { type: "number", message: "Please input the valid age." },
    ],
  } as Record<string, FormRule[]>;
  const submitUser = ({ valid }: FormSubmitEvent) => {
    if (valid) {
      setGroup({ ...group, list: [...group.list, { ...form }] });
      ref.current?.reset();
      setForm({ username: "", age: "" });
      setVisible(false);
    }
  };
  const cancel = () => {
    ref.current?.reset();
    setVisible(false);
  };
  return (
    <div style={{ maxWidth: 512 }}>
      <Form
        name="with-modal"
        model={group}
        onChange={(next) => setGroup(next as typeof group)}
        onSubmit={(e) => message[e.valid ? "success" : "error"](e.valid ? "success" : "failed")}
        rules={rules}
        labelCol={labelCol}
        wrapperCol={wrapperCol}
      >
        <FormItem label="Group" prop="name">
          <Input />
        </FormItem>
        <FormItem label="UserList">
          <Space>
            {group.list.map((item, i) => (
              <Tag theme="fill" key={i}>
                {item.username} - {item.age}
              </Tag>
            ))}
          </Space>
        </FormItem>
        <FormItem wrapperCol={{ offset: 6 }}>
          <Button type="primary" htmlType="submit">
            Submit
          </Button>
          <Button onClick={() => setVisible(true)} style={{ marginLeft: 10 }}>
            Add User
          </Button>
        </FormItem>
      </Form>
      <Modal
        open={visible}
        title="New User"
        width={450}
        onClose={cancel}
        onCancel={cancel}
        onOk={() => ref.current?.submit()}
      >
        <Form
          ref={ref}
          labelCol={labelCol}
          wrapperCol={wrapperCol}
          name="modal"
          model={form}
          onChange={(next) => setForm(next as typeof form)}
          rules={userRules}
          onSubmit={submitUser}
        >
          <FormItem label="Usename" prop="username">
            <Input placeholder="Please input username" />
          </FormItem>
          <FormItem label="Age" prop="age">
            <Input placeholder="Please input age" />
          </FormItem>
        </Form>
      </Modal>
    </div>
  );
}

import { useRef, useState } from "react";
import { Button, Input, message, Form, FormItem, type FormExpose, type FormRule } from "react-kui";
const labelCol = { span: 5 },
  wrapperCol = { span: 16 };
export default function App() {
  const ref = useRef<FormExpose>(null);
  const [form, setForm] = useState({
    fullname: "",
    IDnumber: "",
    password: "",
    confirm_password: "",
  });
  const validateID = (_: FormRule, value: unknown, cb: (e?: Error) => void) =>
    cb(
      typeof value === "string" &&
        value !== "" &&
        !/(^\d{15}$)|(^\d{18}$)|(^\d{17}(\d|X|x)$)/.test(value)
        ? new Error("Please enter the correct ID number")
        : undefined,
    );
  const validatePassword = (_: FormRule, value: unknown, cb: (e?: Error) => void) => {
    cb(!value ? new Error("Please input your password") : undefined);
    if (value) ref.current?.test("confirm_password");
  };
  const validateAgain = (_: FormRule, value: unknown, cb: (e?: Error) => void) =>
    cb(
      !value
        ? new Error("Please input your password again")
        : value !== form.password
          ? new Error("The two passwords do not match.")
          : undefined,
    );
  const rules = {
    fullname: [
      { required: true, message: "Please input your name" },
      { message: "Name must be in Chinese", pattern: /^[\u4e00-\u9fa5]+$/ },
    ],
    IDnumber: [{ validator: validateID }],
    password: [{ validator: validatePassword }],
    confirm_password: [{ validator: validateAgain }],
  };
  return (
    <div style={{ maxWidth: 600 }}>
      <Form
        ref={ref}
        model={form}
        onChange={(next) => setForm(next as typeof form)}
        rules={rules}
        labelCol={labelCol}
        wrapperCol={wrapperCol}
      >
        <FormItem label="Name" prop="fullname">
          <Input clearable />
        </FormItem>
        <FormItem label="ID Card Number" prop="IDnumber">
          <Input placeholder="Optional" />
        </FormItem>
        <FormItem label="Password" prop="password">
          <Input type="password" placeholder="Please input your password" />
        </FormItem>
        <FormItem label="Confirm Password" prop="confirm_password">
          <Input type="password" placeholder="Please confirm your password" />
        </FormItem>
        <FormItem wrapperCol={{ offset: 5 }}>
          <Button
            type="primary"
            onClick={() =>
              ref.current?.validate().then(({ valid }) =>
                message[valid ? "success" : "error"](valid ? "success" : "failed"),
              )
            }
          >
            Submit
          </Button>
          <Button style={{ marginLeft: 10 }} onClick={() => ref.current?.reset()}>
            Reset
          </Button>
        </FormItem>
      </Form>
    </div>
  );
}

