      () =>
        setTime((v) => {
          if (v <= 1) {
            if (timer.current) clearInterval(timer.current);
            return 60;
          }
          return v - 1;
        }),
      1000,
    );
  };
  return (
    <Space vertical block>
      <Input placeholder="Please input username" icon={User} />
