            suitable for developers of any skill level, comprehensive documentation, and support for
            modern React applications.
          </p>
        </div>
      </Skeleton>
      <br />
      <br />
      <Button disabled={loading} onClick={reload}>
        Reload
      </Button>
    </>
  );
}

